from functools import singledispatch

@singledispatch
def dist(seq, i):            # default: the 'base tag' implementation
    for n, v in enumerate(seq):
        if n == i: return v

@dist.register
def _(seq: list, i):         # list -> O(1) path, selected by the argument's type
    return seq[i]

